import ast, os, sys
from collections import defaultdict

# Collect all direct imports from Python source files
root = '/Users/dk/lab-data/oleovista-acers/acers-backend/acers'
imports = set()
local_imports = set()

for dirpath, dirnames, filenames in os.walk(root):
    # Skip common non-source dirs
    if '.git' in dirpath or '__pycache__' in dirpath or '.venv' in dirpath or 'node_modules' in dirpath:
        continue
    # Skip .venv at project root
    rel = os.path.relpath(dirpath, root)
    if rel.startswith('..') or rel.startswith('.venv'):
        continue
    for fn in filenames:
        if not fn.endswith('.py'):
            continue
        fp = os.path.join(dirpath, fn)
        try:
            with open(fp, 'r') as f:
                tree = ast.parse(f.read())
            for node in ast.walk(tree):
                if isinstance(node, ast.Import):
                    for alias in node.names:
                        pkg = alias.name.split('.')[0]
                        imports.add(pkg)
                elif isinstance(node, ast.ImportFrom):
                    if node.module:
                        pkg = node.module.split('.')[0]
                        imports.add(pkg)
                    if node.level and node.level > 0:
                        pass  # relative import
        except Exception as e:
            pass

for i in sorted(imports):
    print(i)
